import { AsyncLocalStorage } from "node:async_hooks";
const als = new AsyncLocalStorage<{ id: number }>();
async function inner(n: number) { await new Promise((r) => setTimeout(r, 1)); return n * 10; }
async function run() {
  const rs = await Promise.all([als.run({ id: 1 }, inner, 1), als.run({ id: 2 }, inner, 2)]);
  console.log(rs, als.getStore()?.id, als.run({ id: 3 }, () => als.getStore()?.id), als.exit(() => als.getStore()));
}
function main(): void { run(); }
